    },
    {
      "name": "Footer",
      "role": "Site-wide links and legal",
      "description": "White (#ffffff) or cream (#f4efea) background, 1px #383838 top border, padding 48–64px vertical. Multi-column link grid with section headers in Aeonik Mono 600 at 14px, #383838, and links in Aeonik Mono 400 at 14px, #383838. Logo + copyright row at the bottom in Aeonik Mono 400 at 12px, #a1a1a1."
    }
